//! Sprites, sounds and music. Every asset is optional (`?T`): a missing file
//! falls back to drawn shapes, or to sound generated by synth.zig.
//!
//! Drop files in an `assets/` folder next to where you run the game:
//!   assets/bird.png      one frame, or a horizontal strip of square frames
//!                        (e.g. 4 frames of 64x64 = a 256x64 image), facing right
//!   assets/shoot.wav  hit.wav  miss.wav  game_over.wav  powerup.wav
//!   assets/music.ogg     (or music.mp3 / music.wav) looping background music

const std = @import("std");
const rl = @import("raylib");
const SoundId = @import("game.zig").SoundId;
const synth = @import("synth.zig");

const music_files = [_][:0]const u8{ "assets/music.ogg", "assets/music.mp3", "assets/music.wav" };
const music_volume = 0.5;

/// Scratch space for the synthesizer. A global `var` lives in static memory
/// (no heap, not on the stack); raylib copies the samples when loading.
var synth_buffer: [synth.max_samples]i16 = undefined;

pub const Assets = struct {
    bird: ?rl.Texture2D = null,
    /// Number of animation frames in `bird` (1 = a still image).
    bird_frames: u32 = 1,
    /// One optional sound per SoundId. EnumArray is a fixed array indexed by enum.
    sounds: std.EnumArray(SoundId, ?rl.Sound) = .initFill(null),
    /// Streaming music from a file, if there is one...
    music: ?rl.Music = null,
    /// ...otherwise the generated loop, replayed whenever it finishes.
    music_loop: ?rl.Sound = null,
    music_on: bool = true,
    audio_ready: bool = false,

    /// Call after `rl.initWindow` (textures need an OpenGL context).
    pub fn load() Assets {
        var a: Assets = .{};

        if (loadTexture("assets/bird.png")) |tex| {
            a.bird = tex;
            // Square frames side by side: frames = width / height.
            a.bird_frames = @intCast(@max(1, @divTrunc(tex.width, tex.height)));
        }

        rl.initAudioDevice();
        a.audio_ready = rl.isAudioDeviceReady();
        if (!a.audio_ready) return a;

        // `inline for` unrolls at compile time, so `id` is comptime-known
        // and `@tagName(id)` can be concatenated with `++` into a literal
        // like "assets/shoot.wav".
        inline for (comptime std.meta.tags(SoundId)) |id| {
            const sound = loadSound("assets/" ++ @tagName(id) ++ ".wav") orelse
                soundFromSamples(synth.effect(id, &synth_buffer));
            a.sounds.set(id, sound);
        }

        for (music_files) |file| {
            if (!rl.fileExists(file)) continue;
            a.music = rl.loadMusicStream(file) catch continue;
            break;
        }
        if (a.music) |m| {
            rl.setMusicVolume(m, music_volume);
            rl.playMusicStream(m);
        } else {
            const loop = soundFromSamples(synth.music(&synth_buffer));
            rl.setSoundVolume(loop, music_volume);
            a.music_loop = loop;
        }
        return a;
    }

    pub fn unload(self: *Assets) void {
        if (self.bird) |t| rl.unloadTexture(t);
        for (std.meta.tags(SoundId)) |id| {
            if (self.sounds.get(id)) |s| rl.unloadSound(s);
        }
        if (self.music) |m| rl.unloadMusicStream(m);
        if (self.music_loop) |s| rl.unloadSound(s);
        if (self.audio_ready) rl.closeAudioDevice();
        self.* = .{};
    }

    /// `pitch` 1.0 = normal; 2.0 = an octave up.
    pub fn play(self: *const Assets, id: SoundId, pitch: f32) void {
        if (self.sounds.get(id)) |s| {
            rl.setSoundPitch(s, pitch);
            rl.playSound(s);
        }
    }

    /// Call once per frame: music streams need to be fed.
    pub fn updateMusic(self: *const Assets) void {
        if (!self.music_on) return;
        if (self.music) |m| rl.updateMusicStream(m);
        if (self.music_loop) |s| {
            if (!rl.isSoundPlaying(s)) rl.playSound(s);
        }
    }

    pub fn toggleMusic(self: *Assets) void {
        self.music_on = !self.music_on;
        if (self.music) |m| {
            if (self.music_on) rl.resumeMusicStream(m) else rl.pauseMusicStream(m);
        }
        if (self.music_loop) |s| {
            if (!self.music_on) rl.stopSound(s);
        }
    }
};

fn soundFromSamples(samples: []i16) rl.Sound {
    return rl.loadSoundFromWave(.{
        .frameCount = @intCast(samples.len),
        .sampleRate = synth.sample_rate,
        .sampleSize = 16,
        .channels = 1,
        // raylib takes a `void*`; @ptrCast converts our typed pointer.
        .data = @ptrCast(samples.ptr),
    });
}

fn loadTexture(path: [:0]const u8) ?rl.Texture2D {
    if (!rl.fileExists(path)) return null;
    // raylib-zig turns a failed load into an error; `catch null` turns that
    // error into "no texture".
    return rl.loadTexture(path) catch null;
}

fn loadSound(path: [:0]const u8) ?rl.Sound {
    if (!rl.fileExists(path)) return null;
    return rl.loadSound(path) catch null;
}
